import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  const PORT = process.env.PORT || 3000;

  // Define your users and roles here:
  const users = [
    { id: 1, name: 'Admin', role: 'admin' },
    { id: 2, name: 'User', role: 'user' }
  ];

  // Define your permissions here:
  const permissions = ['view-users', 'add-users'];

  // Create a mapping of user ID to their role.
  const userRoles = users.reduce((acc, user) => ({
    ...acc,
    [user.id]: user.role
  }), {});

  // Guard functions for different roles
  const adminGuard = async (req, res, next) => {
    if (!req.user || !userRoles[req.user.id]) return res.status(403).json({ error: 'Unauthorized' });
    next();
  };

  const userGuard = async (req, res, next) => {
    if (!req.user) return res.status(403).json({ error: 'Unauthorized' });
    if (!userRoles[req.user.id] === req.user.role) return res.status(403).json({ error: 'Unauthorized' });
    next();
  };

  // Set up global middleware for different roles
  app.use('/api', adminGuard, async (req, res, next) => {
    try {
      await next();
    } catch (err) {
      console.error(err);
      res.status(500).json({ error: err.message });
    }
  });

  app.use('/api', userGuard, async (req, res, next) => {
    try {
      await next();
    } catch (err) {
      console.error(err);
      res.status(500).json({ error: err.message });
    }
  });

  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

bootstrap();
